148	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
149	{
150	    // An attempt the last session left waiting -- its panel closed meanwhile
151	    // -- is dropped before this session can read, and save, its outcome.
152	    abandon_connection();
153	    m_mode         = mode;
154	    m_printer_name = mode == ConversationMode::Add ? std::string() : printer_name;
155	    m_blocks       = json::array();
156	    m_next_block   = 1;
157	    m_opened       = false;
158	    // A new session's page writes its instructions again.
159	    m_instructions.clear();
160	    m_network.clear();
161	    m_credential_action.clear();
162	    m_credential_arguments = json::object();
163	    m_prepared.clear();
164	    m_added.clear();
165	    m_needs_plugin = false;
166	    m_form.reset();
167	
168	    // The session is the one it was opened for. Its opener names a printer
169	    // it has just read -- a saved one, or for a change the stock profile the
170	    // project has selected -- so a name that finds neither is its bug.
171	    if ((m_mode == ConversationMode::Change && about().name.empty()) ||
172	        (m_mode == ConversationMode::Connect && saved(m_printer_name).name.empty()))
173	        throw std::logic_error("A printer conversation was opened for a printer that is not there: " + m_printer_name);
174	
175	    if (m_mode == ConversationMode::Add) {
176	        m_network = m_backend.network_printers();
177	        // A photo is the fastest way in, and the printers already on the
178	        // network are worth naming. Both sit under the opening, where the
179	        // person is deciding what to say.
180	        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
181	        if (!m_network.empty()) {
182	            json found = json::array();
183	            for (const DiscoveredPrinter& printer : m_network)
184	                found.push_back(json{{"name", printer.name}, {"serial", printer.stable_id}, {"online", printer.connected}});
185	            m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""},
186	                                    {"kind", "network"}, {"printers", std::move(found)}});
187	        }
188	    }
189	    // Connecting a Bambu Lab printer that nothing can reach yet: the opening
190	    // says so, and the notice under it offers the plug-in.
191	    if (m_mode == ConversationMode::Connect && saved(m_printer_name).vendor_id == "BBL" &&
192	        m_backend.connection(m_printer_name).needs_network_plugin)
193	        show_plugin_needed({});
194	    m_host.session_changed();
195	}
