410	Result PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
411	{
412	    const json arguments = json::parse(activity.arguments_json);
413	    switch (handler) {
414	    case ToolHandler::PrinterIdentify: return identify(arguments, activity.correlation_id);
415	    case ToolHandler::PrinterAdd: return add(arguments, activity.correlation_id);
416	    case ToolHandler::PrinterChange: return change(arguments);
417	    case ToolHandler::PrinterConnectionStatus: return connection_status(m_printer_name, activity.correlation_id);
418	    case ToolHandler::PrinterConnect: return request_credential(arguments, activity.action_id);
419	    default: return {};
420	    }
421	}
