424	{
425	    const std::vector<std::string> tools = session_tools();
426	    if (std::find(tools.begin(), tools.end(), activity.tool) == tools.end())
427	        return std::nullopt;
428	    if (activity.state == Agent::ToolState::Succeeded)
429	        return json::parse(activity.result_json);
430	    if (activity.state == Agent::ToolState::Failed && activity.error)
431	        return json{{"error", json{{"code", activity.error->code}, {"message", activity.error->message}}}};
432	    return std::nullopt;
