 24	// The nozzle and the loaded spools, as the device last reported them. The
 25	// plate is not among them: MachineObject carries no build-plate type.
 26	void read_reported_hardware(MachineObject& machine, DiscoveredPrinter& printer)
 27	{
 28	    if (const DevExtderSystem* extruders = machine.GetExtderSystem()) {
 29	        printer.nozzle_diameter = extruders->GetNozzleDiameter(0);
 30	        if (extruders->GetTotalExtderCount() > 0 && machine.is_connected())
 31	            printer.nozzle_temperature = extruders->GetNozzleTempCurrent(0);
 32	    }
 33	    if (DevBed* bed = machine.GetBed(); bed != nullptr && machine.is_connected())
 34	        printer.bed_temperature = bed->GetBedTemp();
 35	    if (machine.is_in_printing()) {
 36	        printer.progress_percent = machine.mc_print_percent;
 37	        printer.job              = machine.subtask_name;
 38	    }
 39	    DevFilaSystem* filaments = machine.GetFilaSystem();
 40	    if (!filaments) return;
 41	    for (const auto& [ams_id, ams] : filaments->GetAmsList()) {
 42	        if (!ams) continue;
 43	        if (printer.ams_name.empty())
 44	            printer.ams_name = ams->GetAmsType() == DevAms::AMS_LITE ? "AMS lite" : "AMS";
 45	        for (const auto& [tray_id, tray] : ams->GetTrays()) {
 46	            if (!tray || !tray->is_exists) continue;
 47	            const std::string material = tray->sub_brands.empty() ? tray->get_display_filament_type() : tray->sub_brands;
 48	            if (material.empty()) continue;
 49	            printer.spools.push_back({(tray->is_bbl ? "Bambu " : "") + material, reported_colour(*tray),
 50	                                      tray->get_display_filament_type()});
 51	        }
 52	    }
 53	    // The external spool holder, which a printer without an AMS feeds from.
 54	    for (const DevAmsTray& tray : machine.vt_slot) {
 55	        if (!tray.is_exists || tray.get_display_filament_type().empty()) continue;
 56	        const std::string material = tray.sub_brands.empty() ? tray.get_display_filament_type() : tray.sub_brands;
 57	        printer.spools.push_back({(tray.is_bbl ? "Bambu " : "") + material, reported_colour(tray),
 58	                                  tray.get_display_filament_type()});
 59	    }
 60	}
