 78	DiscoveredPrinter snapshot(const std::string& id, MachineObject& machine, const MachineObject* selected)
 79	{
 80	    DiscoveredPrinter printer{id, machine.get_dev_name(), machine.get_dev_ip(), machine.printer_type,
 81	                              machine.connection_type(), has_recent_printer_data(machine)};
 82	    // Upstream's own predicate, never a copy of it: the list of states that
 83	    // count as printing has been got wrong here before.
 84	    printer.activity = !printer.connected              ? PrinterActivity::Offline :
 85	                       machine.is_in_printing()         ? PrinterActivity::Printing :
 86	                                                          PrinterActivity::Idle;
 87	    if (machine.last_update_time.time_since_epoch().count() != 0)
 88	        printer.observed_at_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
 89	                                     machine.last_update_time.time_since_epoch())
 90	                                     .count();
 91	    printer.selected = &machine == selected;
 92	    read_reported_hardware(machine, printer);
 93	    return printer;
 94	}
