 96	void sort_printers(std::vector<DiscoveredPrinter>& printers)
 97	{
 98	    std::sort(printers.begin(), printers.end(), [](const DiscoveredPrinter& a, const DiscoveredPrinter& b) {
 99	        if (a.connected != b.connected) return a.connected > b.connected;
100	        if (a.name != b.name) return a.name < b.name;
101	        return a.stable_id < b.stable_id;
102	    });
