107	std::vector<DiscoveredPrinter> discover_printers(bool include_unreachable)
108	{
109	    std::vector<DiscoveredPrinter> result;
110	    DeviceManager* devices = wxGetApp().getDeviceManager();
111	    if (!devices) return result;
112	    const MachineObject* selected = devices->get_selected_machine();
113	    for (const auto& [id, machine] : devices->get_my_machine_list()) {
114	        if (!machine) continue;
115	        const bool reachable = machine->is_online() || machine->is_connected();
116	        if (!reachable && !include_unreachable) continue;
117	        result.push_back(snapshot(id, *machine, selected));
118	    }
119	    sort_printers(result);
120	    return result;
121	}
