129	    // What the network search answered, with or without an access code,
130	    // and the printers bound to the signed-in account: the candidates
131	    // OrcaPrinterBackend::connection() offers, by the same test.
132	    auto machines = devices->get_local_machinelist();
133	    for (const auto& [id, machine] : devices->get_my_cloud_machine_list())
134	        machines[id] = machine;
135	    for (const auto& [id, machine] : machines) {
136	        if (!machine || (machine->is_lan_mode_printer() && !machine->is_avaliable())) continue;
137	        if (!machine->is_lan_mode_printer() && !machine->is_online()) continue;
138	        result.push_back(snapshot(id, *machine, selected));
139	    }
140	    sort_printers(result);
141	    return result;
142	}
